class EnergieflussCardEditor extends HTMLElement {
  constructor() {
    super();
    this._config = {};
    this._built = false;
    this._consLen = -1;
  }

  setConfig(config) {
    const c = JSON.parse(JSON.stringify(config || {}));
    // alte Felder übernehmen
    (c.consumers || []).forEach((cs) => {
      if (cs.switch_entity && !cs.hold_action) {
        cs.hold_action = { action: 'perform-action', perform_action: 'homeassistant.toggle', target: { entity_id: cs.switch_entity } };
      }
      delete cs.switch_entity;
    });
    ['pv', 'grid', 'battery', 'home', 'wallbox'].forEach((k) => {
      if (c[k]?.navigation_path && !c[k].tap_action) c[k].tap_action = { action: 'navigate', navigation_path: c[k].navigation_path };
      if (c[k]) delete c[k].navigation_path;
    });
    this._config = c;
    if (!this._built) this._build();
    else this._refresh();
  }

  set hass(hass) {
    this._hass = hass;
    this.querySelectorAll('ha-form').forEach((f) => { f.hass = hass; });
  }

  async _loadHa() {
    if (customElements.get('ha-form') && customElements.get('ha-entity-picker')) return;
    try {
      const helpers = await window.loadCardHelpers();
      const card = await helpers.createCardElement({ type: 'entities', entities: [] });
      await card.constructor.getConfigElement();
    } catch (e) { /* ignorieren */ }
  }

  async _build() {
    this._built = true;
    await this._loadHa();
    this.innerHTML = `
      <style>
        .ef-cons-panel { margin-top:8px; display:block; }
        .ef-item { margin:6px 0; border:1px solid var(--divider-color, #555); border-radius:10px; }
        .ef-row { display:flex; align-items:center; gap:6px; padding:6px 8px; }
        .ef-title { flex:1; min-width:0; cursor:pointer; }
        .ef-name { font-size:14px; color:var(--primary-text-color); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
        .ef-ent { font-size:12px; color:var(--secondary-text-color); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
        .ef-row button { background:none; border:1px solid var(--divider-color, #555); color:var(--primary-text-color);
          border-radius:6px; width:34px; height:32px; font-size:15px; cursor:pointer; flex:none; }
        .ef-item.open .ef-edit { transform:rotate(180deg); }
        .ef-detail { display:none; padding:0 8px 8px; }
        .ef-item.open .ef-detail { display:block; }
        .ef-btns { display:flex; justify-content:flex-end; margin:8px 0 0; }
        .ef-btns button, .ef-add { background:none; border:1px solid var(--divider-color, #555); color:var(--primary-text-color);
          border-radius:6px; padding:4px 12px; font-size:14px; cursor:pointer; }
        .ef-add { margin:8px 0 4px; padding:8px 12px; width:100%; }
        .ef-hint { font-size:12px; color:var(--secondary-text-color); margin:4px 0 8px; }
        .ef-inner { padding:0 4px 8px; }
      </style>
      <div class="ef-main"></div>
      <ha-expansion-panel class="ef-cons-panel" outlined>
        <div class="ef-inner">
          <div class="ef-hint">Reihenfolge mit den Pfeilen festlegen. Ein Bild hat Vorrang vor dem Symbol.</div>
          <div class="ef-cons"></div>
          <button class="ef-add">+ Verbraucher hinzufügen</button>
        </div>
      </ha-expansion-panel>`;
    const main = document.createElement('ha-form');
    main.hass = this._hass;
    main.schema = EF_SCHEMA;
    main.computeLabel = (s) => EF_LABELS[s.name] || s.title || s.name;
    main.addEventListener('value-changed', (e) => {
      e.stopPropagation();
      const v = { ...e.detail.value };
      v.consumers = this._config.consumers || [];
      v.type = this._config.type;
      this._config = v;
      this._fire();
    });
    this._main = main;
    this.querySelector('.ef-main').appendChild(main);
    this.querySelector('.ef-add').addEventListener('click', () => {
      const list = [...(this._config.consumers || [])];
      list.push({ entity: '', name: 'Neuer Verbraucher', icon: 'mdi:flash', threshold: 5 });
      this._config = { ...this._config, consumers: list };
      this._openIdx = list.length - 1;
      this._renderConsumers();
      this._fire();
    });
    this._refresh();
  }

  _panelHeader() {
    const p = this.querySelector('.ef-cons-panel');
    if (p) p.header = `Verbraucher (${(this._config.consumers || []).length})`;
  }

  _refresh() {
    if (!this._main) return;
    const data = efMerge(EF_DEFAULTS, this._config);
    delete data.consumers;
    this._main.data = data;
    const len = (this._config.consumers || []).length;
    if (len !== this._consLen) this._renderConsumers();
    else {
      this.querySelectorAll('.ef-item').forEach((it, i) => {
        const cs = this._config.consumers[i];
        it.querySelector('ha-form').data = cs;
        if (it._setHead) it._setHead(cs);
      });
    }
    this._panelHeader();
  }

  _renderConsumers() {
    const box = this.querySelector('.ef-cons');
    if (!box) return;
    const list = this._config.consumers || [];
    this._consLen = list.length;
    box.innerHTML = '';
    list.forEach((cs, i) => {
      const item = document.createElement('div');
      item.className = 'ef-item' + (this._openIdx === i ? ' open' : '');
      item.innerHTML = `<div class="ef-row">
          <div class="ef-title"><div class="ef-name"></div><div class="ef-ent"></div></div>
          <button data-a="up" title="nach oben">&#8593;</button><button data-a="down" title="nach unten">&#8595;</button>
          <button data-a="edit" class="ef-edit" title="bearbeiten">&#9662;</button>
        </div><div class="ef-detail"><div class="ef-btns"><button data-a="del">&#10005; Entfernen</button></div></div>`;
      const setHead = (c) => {
        item.querySelector('.ef-name').textContent = c?.name || c?.entity || `Verbraucher ${i + 1}`;
        item.querySelector('.ef-ent').textContent = c?.entity || '';
      };
      setHead(cs);
      item._setHead = setHead;
      const toggle = () => item.classList.toggle('open');
      item.querySelector('.ef-title').addEventListener('click', toggle);
      item.querySelectorAll('button').forEach((b) => b.addEventListener('click', (ev) => {
        ev.stopPropagation();
        if (b.dataset.a === 'edit') toggle(); else this._move(i, b.dataset.a);
      }));
      const f = document.createElement('ha-form');
      f.hass = this._hass;
      f.schema = EF_CONSUMER_SCHEMA;
      f.data = cs;
      f.computeLabel = (sch) => (sch.name === 'threshold' ? EF_LABELS.threshold_c : (EF_LABELS[sch.name] || sch.title || sch.name));
      f.addEventListener('value-changed', (e) => {
        e.stopPropagation();
        const l = [...(this._config.consumers || [])];
        l[i] = e.detail.value;
        this._config = { ...this._config, consumers: l };
        setHead(l[i]);
        this._fire();
      });
      item.querySelector('.ef-detail').insertBefore(f, item.querySelector('.ef-detail .ef-btns'));
      box.appendChild(item);
    });
    this._openIdx = null;
    this._panelHeader();
  }

  _move(i, a) {
    const l = [...(this._config.consumers || [])];
    let open = i;
    if (a === 'del') { l.splice(i, 1); open = null; }
    if (a === 'up' && i > 0) { [l[i - 1], l[i]] = [l[i], l[i - 1]]; open = i - 1; }
    if (a === 'down' && i < l.length - 1) { [l[i + 1], l[i]] = [l[i], l[i + 1]]; open = i + 1; }
    this._config = { ...this._config, consumers: l };
    this._openIdx = open;
    this._renderConsumers();
    this._fire();
  }

  _fire() {
    this.dispatchEvent(new CustomEvent('config-changed', { detail: { config: this._clean(this._config) }, bubbles: true, composed: true }));
  }

  // Nur Werte speichern, die von den Standardwerten abweichen
  _clean(cfg) {
    const strip = (val, def) => {
      if (val && typeof val === 'object' && !Array.isArray(val) && def && typeof def === 'object') {
        const o = {};
        for (const [k, v] of Object.entries(val)) {
          const s = strip(v, def[k]);
          if (s !== undefined) o[k] = s;
        }
        return Object.keys(o).length ? o : undefined;
      }
      if (val === undefined || val === '' || val === null) return undefined;
      if (def !== undefined && JSON.stringify(val) === JSON.stringify(def)) return undefined;
      return val;
    };
    const out = { type: cfg.type || 'custom:energiefluss-card' };
    for (const [k, v] of Object.entries(cfg)) {
      if (k === 'type') continue;
      if (k === 'consumers') { out.consumers = v; continue; }
      const s = strip(v, EF_DEFAULTS[k]);
      if (s !== undefined) out[k] = s;
    }
    return out;
  }
}

if (!customElements.get('energiefluss-card')) customElements.define('energiefluss-card', EnergieflussCard);
if (!customElements.get('energiefluss-card-editor')) customElements.define('energiefluss-card-editor', EnergieflussCardEditor);
